nal rows and workbook hash retained.","2024-panini-select-wwe-checklist","2024-panini-select-wwe","https://xcdn.checklistinsider.com/public/2024/10/2024-Panini-Select-WWE-Wrestling-Checklist-Downloads-Excel-spreadsheet.xlsx","2024-panini-select-wwe-comparison","https://www.checklistcenter.com/2024-panini-select-wwe-wrestling-card-checklist/","2024-panini-select-wwe-release","https://www.checklistinsider.com/2024-panini-select-wwe-wrestling","2024-panini-select-wwe-manufacturer","2024-panini-select-wwe-distributor","https://gogts.net/wp-content/uploads/2024/10/2024-Panini-Select-WWE-Trading-Cards-Checklist.xls","All 11234 rows reconciled. 63 instances of one Seth nickname mojibake string repaired only for comparison/display. Original rows and workbook hash retained.","2024-panini-photogenic-wwe-checklist","2024-panini-photogenic-wwe","https://xcdn.checklistinsider.com/public/2024/09/2024-Panini-PhotoGenic-WWE-Wrestling-Checklist-Downloads-Excel-spreadsheet.xlsx","2024-panini-photogenic-wwe-comparison","https://www.checklistcenter.com/2024-panini-photogenic-wwe-wrestling-card-checklist/","2024-panini-photogenic-wwe-release","https://www.checklistinsider.com/2024-panini-photogenic-wwe","2024-panini-photogenic-wwe-manufacturer"],"r":[[0,1,2,3,4,5],[6,1,7,8,9,10],[11,1,12,13,14,15],[16,1,17,18,19,20],[21,1,22,23,24,25],[26,27,2,3,28,5],[29,27,7,8,30,10],[31,27,12,13,32,15],[33,27,17,18,19,20],[34,27,22,23,35,36],[37,38,2,3,39,5],[40,38,7,8,41,10],[42,38,12,13,43,15],[44,38,17,18,19,20]]}'::jsonb p) d cross join lateral jsonb_array_elements(p->'r') r(value);
do $$ begin
 if exists(select 1 from public.catalogue_sources t join desired_catalogue_sources e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.source is distinct from e.source or t.purpose is distinct from e.purpose or t.url is distinct from e.url or t.notes is distinct from e.notes)
 then raise exception 'Conflicting catalogue_sources identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_sources(id,set_id,source,purpose,url,notes) select id,set_id,source,purpose,url,notes from desired_catalogue_sources on conflict do nothing;
do $$ begin
 if (select count(*) from public.catalogue_sets where id='2024-panini-three-count-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2024-panini-three-count-wwe')<>13
 or (select count(*) from public.catalogue_cards where set_id='2024-panini-three-count-wwe')<>415
 or (select count(*) from public.catalogue_variants where set_id='2024-panini-three-count-wwe')<>3333
 or (select count(*) from public.catalogue_parallel_rules where set_id='2024-panini-three-count-wwe')<>131
 or (select count(*) from public.catalogue_sources where set_id='2024-panini-three-count-wwe')<>5
 or (select count(*) from public.catalogue_sets where id='2024-panini-select-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2024-panini-select-wwe')<>21
 or (select count(*) from public.catalogue_cards where set_id='2024-panini-select-wwe')<>789
 or (select count(*) from public.catalogue_variants where set_id='2024-panini-select-wwe')<>11234
 or (select count(*) from public.catalogue_parallel_rules where set_id='2024-panini-select-wwe')<>202
 or (select count(*) from public.catalogue_sources where set_id='2024-panini-select-wwe')<>5
 or (select count(*) from public.catalogue_sets where id='2024-panini-photogenic-wwe')<>1
 or (select count(*) from public.catalogue_subsets where set_id='2024-panini-photogenic-wwe')<>12
 or (select count(*) from public.catalogue_cards where set_id='2024-panini-photogenic-wwe')<>395
 or (select count(*) from public.catalogue_variants where set_id='2024-panini-photogenic-wwe')<>2924
 or (select count(*) from public.catalogue_parallel_rules where set_id='2024-panini-photogenic-wwe')<>76
 or (select count(*) from public.catalogue_sources where set_id='2024-panini-photogenic-wwe')<>4
 or (select count(*) from public.catalogue_sets)<>45
 or (select count(*) from public.catalogue_cards)<>22215
 or exists(select 1 from public.catalogue_variants v left join public.catalogue_cards c on c.id=v.card_id where v.set_id in ('2024-panini-three-count-wwe','2024-panini-select-wwe','2024-panini-photogenic-wwe') and (c.id is null or c.set_id<>v.set_id))
 or exists(select 1 from public.catalogue_subsets s where s.set_id in ('2024-panini-three-count-wwe','2024-panini-select-wwe','2024-panini-photogenic-wwe') and s.card_count<>(select count(*) from public.catalogue_cards c where c.set_id=s.set_id and c.subset_code=s.subset_code))
 or exists(select row from before_catalogue_sets except all select to_jsonb(t) from public.catalogue_sets t)
 or exists(select row from before_catalogue_subsets except all select to_jsonb(t) from public.catalogue_subsets t)
 or exists(select row from before_catalogue_cards except all select to_jsonb(t) from public.catalogue_cards t)
 or exists(select row from before_catalogue_variants except all select to_jsonb(t) from public.catalogue_variants t)
 or exists(select row from before_catalogue_parallel_rules except all select to_jsonb(t) from public.catalogue_parallel_rules t)
 or exists(select row from before_catalogue_sources except all select to_jsonb(t) from public.catalogue_sources t)
 or exists(select row from before_collection_items except all select to_jsonb(t) from public.collection_items t)
 or exists(select row from before_reference_images except all select to_jsonb(t) from public.reference_images t)
 or exists(select to_jsonb(t) from public.collection_items t except all select row from before_collection_items)
 or exists(select to_jsonb(t) from public.reference_images t except all select row from before_reference_images)
 then raise exception 'Count, linkage or preservation check failed'; end if;
end $$;
select 'verified' as result,(select count(*) from public.catalogue_cards) as cards,(select count(*) from public.collection_items) as collections;
commit;
